$dest = "C:\Users\M2-W10\Desktop\CONSOLIDADO_VIMUME_TOTAL"
$keywords = @("*Vimume*", "*Musicoterapia*", "*Tercera Edad*", "*Silver Economy*", "*Edad Dorada*", "*Adulto Mayor*", "*Geriatria*", "*Manual de Marca*")
$excludeFolders = @("*MUSICA_PERSONAL*", "*Coleccion_FLAC*", "*Recycle.Bin*")

# 2. Crear la carpeta si no existe
if (!(Test-Path $dest)) { 
    New-Item -ItemType Directory -Path $dest -Force | Out-Null
    Write-Host "Carpeta creada en: $dest" -ForegroundColor Green
}

# 3. Proceso de búsqueda y copia
Write-Host "Iniciando redada de archivos para VIMUME..." -ForegroundColor Yellow

foreach ($k in $keywords) {
    Write-Host "Buscando: $k" -ForegroundColor Cyan
    # Buscamos en H: (tu disco de archivos) y en el Escritorio de C:
