             Where-Object { 
                $path = $_.FullName
                $keep = $true
                foreach($ex in $excludeFolders){ if($path -like $ex){ $keep = $false } }
                $keep 
             }

    foreach ($f in $files) {
        $targetFile = Join-Path $dest $f.Name
        # Si ya existe un archivo con ese nombre, le ponemos la fecha para no perder versiones
        if (Test-Path $targetFile) {
            $newName = $f.BaseName + "_" + (Get-Date -Format "yyyyMMdd_HHmm") + $f.Extension
            $targetFile = Join-Path $dest $newName
        }
        try {
            Copy-Item -Path $f.FullName -Destination $targetFile -Force -ErrorAction Stop
            Write-Host "  [OK] $($f.Name)" -ForegroundColor Gray
        } catch {
            Write-Host "  [ERROR] No se pudo copiar: $($f.Name)" -ForegroundColor Red
        }
    }
}

Write-Host "`n¡OPERACIÓN COMPLETADA!" -ForegroundColor Green
